import { evidence } from './paperEvidence.js';
const slides=[
{k:'01 · OPENING',t:'Mental World Modeling',html:`<p class="subtitle">从「识别人的状态」到「模拟人的心理世界」</p><div class="flow"><div class="node">Physical World</div><div class="arrow">+</div><div class="node">Mental World</div><div class="arrow">→</div><div class="node">Human Action</div></div><div class="callout">今天要回答两个问题：<strong>AI 要预测人的行动，需要知道什么？它如何像专家一样根据情境改变推理方式？</strong></div><p class="note">Hao Fei · Yiran Zhao · Oxford × NUS · arXiv 2026</p>`},
{k:'02 · A SIMPLE STORY',t:'一个房间，两个「世界」',html:`<div class="question">这一页在回答：为什么只建模物理世界不够？</div><div class="sample"><div class="sample-story"><b>事实</b><br>礼物被藏在衣柜里。Alice 知道位置，Bob 没看见，他还在客厅寻找。<br><br><b>同一物理场景</b><br>衣柜、礼物和人的位置对两人都相同。</div><div class="stack"><div class="card"><span class="mini-label">ALICE 的世界</span><h3>她相信礼物在衣柜</h3><p>目标：保持惊喜<br>可能行动：把 Bob 引向别处</p></div><div class="card"><span class="mini-label">BOB 的世界</span><h3>他不知道礼物在哪</h3><p>目标：找到礼物<br>可能行动：继续搜索</p></div></div></div><div class="callout">预测人的下一步，不仅要知道「真实世界是什么」，还要知道「<strong>这个人以为世界是什么</strong>」。</div>`},
{k:'03 · THE QUESTION',t:'AI 应该把「人」建模成什么？',html:`<div class="question">为什么会有这个问题？</div><p class="plain">传统系统常把人当成待分类对象：输入表情、语音和行为，输出「焦虑」「高压」或「外向」。但分类没有回答：人为什么这样行动，事件发生后又会怎么变。</p><div class="compare"><div class="card"><h3>传统识别</h3><div class="stack"><div class="step">看到什么信号？</div><div class="step">属于什么标签？</div><div class="step hot">输出：Emotion / Stress / Trait</div></div></div><div class="vs">→</div><div class="card"><h3>Mental World Model</h3><div class="stack"><div class="step">他看到、知道什么？</div><div class="step">他相信、想要什么？</div><div class="step">事件会如何改变他？</div><div class="step hot">输出：Action / Future</div></div></div></div><div class="callout"><strong>论文主张：</strong>情绪不是终点，而是人的动态模型中的一个状态变量。</div>`},
{k:'04 · THE STATE',t:'「心理世界」里有什么？',html:`<div class="question">可以把它理解为一张会随事件更新的「人物卡」</div><div class="radial"><div class="core">Mental<br>World State</div>${['他知道什么？<br>belief / knowledge','他在关注什么？<br>attention','他想要什么？<br>goal / intention','他感受如何？<br>emotion','他通常偏好什么？<br>preference / value','什么是允许的？<br>norm','他和别人是什么关系？<br>social relation'].map((x,i)=>`<div class="orbit" style="--a:${i*51.43}deg">${x}</div>`).join('')}</div><div class="callout">它不是「读心」：这些变量都是根据行为和情境得到的<strong>可质疑假设</strong>，而不是对内心的测量。</div>`},
{k:'05 · WHAT MAKES IT DYNAMIC',t:'不是写一份报告，而是继续推演',html:`<div class="question">「世界模型」比「心理分析」多了什么？</div><div class="flow"><div class="node">当前场景<br>Observation t</div><span class="arrow">→</span><div class="node">当前心理状态<br>State t</div><span class="arrow">→</span><div class="node">事件 / 行动</div><span class="arrow">→</span><div class="node">更新后状态<br>State t+1</div><span class="arrow">→</span><div class="node">下一步行动</div></div><div class="grid-2" style="margin-top:28px"><div class="card"><span class="mini-label">RECOGNITION</span><h3>他现在紧张吗？</h3><p>把人当成当下时刻的待分类对象。</p></div><div class="card"><span class="mini-label">WORLD MODELING</span><h3>如果追问这个话题，他会怎么变？</h3><p>把人当成会被事件改变、并继续行动的系统。</p></div></div>`},
{k:'06 · HOW MENTIS WORKS',t:'MENTIS 究竟做了什么？',html:`<div class="question">一句话：不直接猜答案，先模拟每个选择会导致什么</div><div class="pipeline">${[['01','整理事实','礼物在衣柜；Bob 没看见'],['02','切换视角','Bob 能看到、知道什么？'],['03','拆解行动','物理动作 + 心理社会含义'],['04','逐一模拟','对 A–F 每个候选项预测后果'],['05','比较分支','物理可行？心理一致？社会合适？'],['06','最后选择','模拟完成后才决定']].map(([n,h,p])=>`<div class="stage"><b>${n}</b><strong>${h}</strong><small style="display:block;color:var(--muted);margin-top:8px;line-height:1.4">${p}</small></div>`).join('')}</div><div class="callout"><strong>关键约束：</strong>不能先选答案，再编解释。答案必须来自「当前状态 → 局部观察 → 候选行动 → 后续状态」。</div>`},
{k:'07 · ONE BENCHMARK CASE',t:'一条 Menti-Bench 样本长什么样？',html:`<div class="question">先看一条，再看 448 这个数字</div><div class="sample"><div class="sample-story"><span class="mini-label">INPUT · 系统收到的内容</span><b>场景：</b>Amy 今晚要完成画作。Lisa 的运动包挡住了画板。之前 Lisa 曾说，移动她的物品前要先询问。Lisa 误以为 Amy 已经不画了。<br><br><b>问题：</b>Amy 下一步最可能做什么？</div><div class="stack"><div class="option gold"><b>A · Gold</b><br>解释画还没完成，请 Lisa 移开包。</div><div class="option"><b>D · 强干扰项</b><br>自己直接把 Lisa 的包移开。</div><div class="card"><span class="mini-label">WHY A, NOT D?</span><p>两者都解决物理挡路问题；但 D 违反既有规范，并可能损害关系。</p></div></div></div><div class="callout">合理行动同时取决于<strong>物理、信念、目标和规范</strong>。</div>`},
{k:'08 · WHAT THE EXPERIMENT DID',t:'这个实验究竟做了什么？',html:`<div class="question">从输入到分数，完整走一遍</div><div class="grid-2"><div class="card"><div class="explain-row"><b>1 · 材料</b><span>448 个虚构日常决策场景：320 文本、100 图像、28 有声视频。</span></div><div class="explain-row"><b>2 · 任务</b><span>每条指定一个目标人物，从 6 个候选中选其下一步行动。</span></div><div class="explain-row"><b>3 · 标准答案</b><span>人工标注正确行动、当前状态、目标人观察和 6 个后续状态。</span></div><div class="explain-row"><b>4 · 比较</b><span>让同一批基础模型用 7 种推理方式，看哪种结构提高预测。</span></div></div><div><div class="big-number">448</div><p class="plain">cases × 6 个候选分支<br>= <strong class="accent">2,688</strong> 个 successor states</p><p class="plain"><strong>78%</strong> 的场景有至少两人，大多数题目需要理解他人的信念或意图。</p></div></div><div class="callout">真正被验证的问题：<strong>显式建模心理状态和后续变化，是否能提高下一步行动的预测？</strong></div>`},
{k:'09 · CONTROLLED COMPARISON',t:'如何证明是「结构」有用，而不只是想得更久？',html:`<div class="question">把能力一层层加上去，相邻比较定位增益来自哪里</div><div class="grid-2"><div class="stack">${['S0 · 只看 6 个选项，不看故事','S1 · 看故事后直接选答案','S2 · 回答前先自由推理 CoT','S3 · 独立推理 6 次后投票','S4 · 先写自由文本的世界状态','S5 · 拆出结构化物理 + 心理状态','S6 · 加入视角、6 个分支模拟和比较'].map((x,i)=>`<div class="step ${i===6?'hot':''}">${x}</div>`).join('')}</div><div class="card"><h3>相邻两层在问什么？</h3><div class="explain-row"><b>S1 → S2</b><span>显式推理有没有用？</span></div><div class="explain-row"><b>S3 → S4</b><span>更多采样，还是先表示状态更有用？</span></div><div class="explain-row"><b>S4 → S5</b><span>结构化字段是否额外有价值？</span></div><div class="explain-row"><b>S5 → S6</b><span>真正模拟每个后果是否有用？</span></div><p class="note">同一批 448 条题目，并在 8 个基础模型上重复。</p></div></div>`},
{k:'10 · MAIN RESULT',t:'结果：多想几次，仍然不等于世界建模',html:`<div class="bars">${[['S0 仅选项',31.3],['S1 直接回答',63.3],['S2 + CoT',74.6],['S3 + 六次投票',77.9],['S4 + 自由状态',80.3],['S5 + 结构状态',82.6],['S6 完整 MWM',87.9]].map(([n,v])=>`<div class="bar-row"><span>${n}</span><div class="bar-track"><div class="bar-fill" style="--w:${v}%"></div></div><span class="bar-val">${v}</span></div>`).join('')}</div><div class="grid-2" style="margin-top:18px"><div class="callout"><strong>现象 1：</strong>每加一层建模承诺，8 个模型的 F1 都提升。</div><div class="callout"><strong>现象 2：</strong>最弱模型 + MWM 84.9，超过最强模型 + 六次投票 83.6。</div></div><p class="note">F1 可简单理解为「选对下一步行动的综合得分」；人类参考为 98.5。</p>`},
{k:'11 · WHY STRUCTURE HELPS',t:'还能怎样确认「结构」真的在起作用？',html:`<div class="question">反向实验：从完整 MWM 中拿掉一个组件</div><div class="bars">${[['完整 MWM',87.9],['物理与心理分开模拟',81.5],['拿掉心理通道',75.8],['拿掉物理通道',71.4]].map(([n,v])=>`<div class="bar-row"><span>${n}</span><div class="bar-track"><div class="bar-fill" style="--w:${v}%"></div></div><span class="bar-val">${v}</span></div>`).join('')}</div><div class="grid-3" style="margin-top:24px"><div class="card"><h3>心理不能少</h3><p>否则无法区分具有不同信念的人。</p></div><div class="card"><h3>物理也不能少</h3><p>心理推理必须受到可见性、位置和可行动作约束。</p></div><div class="card"><h3>两者必须联动</h3><p>行动同时改变环境、信念、情绪和关系。</p></div></div>`},
{k:'12 · WHERE IT HELPS',t:'什么问题最需要这种建模？',html:`<div class="question">比较完整 MWM 和直接回答在不同场景中的差值</div><div class="bars">${[['人际互动',26.4],['风险 / 规范',19.7],['空间 / 感知',18.5],['物体 / 资源',14.0]].map(([n,v])=>`<div class="bar-row"><span>${n}</span><div class="bar-track"><div class="bar-fill" style="--w:${v/30*100}%"></div></div><span class="bar-val">+${v}</span></div>`).join('')}</div><div class="callout">人际场景中，直接回答最弱，完整 MWM 反而最强。<strong>问题越依赖隐藏的信念、意图、关系与规范，显式建模越有价值。</strong></div>`},
{k:'13 · THE BOTTLENECK',t:'当前最大的错误发生在哪里？',html:`<div class="question">把每个中间阶段依次替换成人工标注的正确结果，看哪个帮助最大</div><div class="grid-2"><div class="bars">${[['Gold Action',.7],['Gold Observation',1.7],['Gold State',2.8],['Gold Transition',3.5]].map(([n,v])=>`<div class="bar-row"><span>${n}</span><div class="bar-track"><div class="bar-fill" style="--w:${v/4*100}%"></div></div><span class="bar-val">+${v}</span></div>`).join('')}</div><div class="card"><span class="mini-label">PLAIN-LANGUAGE READING</span><div class="big-number">45%</div><p>只把「后续状态模拟」换成标准答案，就恢复剩余人类差距的 45%。</p></div></div><div class="callout">当前更难的不是说「这个人现在怎样」，而是模拟「<strong>这件事发生之后，人和环境会一起怎么变</strong>」。</div>`},
{k:'14 · FROM STATE TO REASONING',t:'但「动态」还可以再往前一步',html:`<div class="question">我们的延展：泛化问题可能不只是 transition 不准</div><div class="levels"><div class="level"><strong>LEVEL 1</strong><div><h3>Dynamic Signal</h3><p>压力、情绪和行为指标随时间变化。</p></div></div><div class="level"><strong>LEVEL 2</strong><div><h3>Dynamic State</h3><p>根据事件和行动，预测 State t 如何变成 State t+1。</p></div></div><div class="level"><strong>LEVEL 3</strong><div><h3 class="accent">Dynamic Reasoning</h3><p>情境改变时，重要变量、解释假设、证据权重和推理深度也一起改变。</p></div></div></div>`},
{k:'15 · WHY GENERALIZATION IS HARD',t:'同一信号，在不同情境中可能意味着不同事情',html:`<div class="question">专家不是记住更多「A + B = C」，而是知道什么时候某个信号才有意义</div><p class="quote">High stress + gaze avoidance</p><div class="grid-2"><div class="card"><h3>结构化面试</h3><p>可能是紧张或被评价时的担忧。</p></div><div class="card"><h3>讯问情境</h3><p>可能是认知负荷、担忧，也可能是社交焦虑。</p></div><div class="card"><h3>疲劳驾驶</h3><p>gaze change 可能首先指向警觉性下降。</p></div><div class="card"><h3>心理咨询</h3><p>需结合话题、关系阶段和个人历史。</p></div></div><div class="callout"><span class="tag">OUR INFERENCE</span> 泛化差可能不是单一模型不够准，而是系统没有根据情境改变「应该怎样解释证据」。</div>`},
{k:'16 · ADAPTIVE REASONING',t:'真正像专家一样思考，需要五种能力',html:`<div class="grid-2"><div class="stack">${['① 动态决定「应该看什么」','② 同时维护多个竞争解释','③ 寻找支持证据，也主动寻找反证','④ 根据问题决定推理几层','⑤ 知道何时证据不足，需要追问或暂停'].map((x,i)=>`<div class="step ${i===4?'hot':''}">${x}</div>`).join('')}</div><div class="card"><span class="tag">OUR ARCHITECTURE</span><h3 style="margin-top:16px">Adaptive Psychological Reasoning</h3><div class="hypotheses"><div class="hypo"><span>H1 · Anxiety</span><b>42%</b><i style="--p:42%"></i></div><div class="hypo"><span>H2 · Cognitive load</span><b>31%</b><i style="--p:31%"></i></div><div class="hypo"><span>H3 · Fatigue</span><b>18%</b><i style="--p:18%"></i></div></div><p>系统不是立即宣布「他就是焦虑」，而是问：<strong>接下来看什么，最能区分 H1 和 H2？</strong></p></div></div>`},
{k:'17 · CLOSING',t:'我们要做的，不是一份更漂亮的心理报告',html:`<div class="question">把论文结论、我们的延展和验证标准收束在一起</div><div class="flow"><div class="node">感知信号</div><span class="arrow">→</span><div class="node">结构化状态</div><span class="arrow">→</span><div class="node">状态转移</div><span class="arrow">→</span><div class="node">竞争假设</div><span class="arrow">→</span><div class="node">主动找证据</div><span class="arrow">→</span><div class="node">决策或暂停</div></div><div class="grid-3" style="margin-top:28px"><div class="card"><span class="mini-label">PAPER PROVES</span><h3>结构有用</h3><p>显式状态与分支模拟提高行动预测。</p></div><div class="card"><span class="mini-label">PAPER FINDS</span><h3>转移是瓶颈</h3><p>最大单项误差来自 successor-state simulation。</p></div><div class="card"><span class="mini-label">OUR NEXT QUESTION</span><h3>推理也要动态</h3><p>系统能否根据情境改变状态、证据、假设与深度？</p></div></div><div class="callout"><strong>验证底线：</strong>修改 belief / goal / context 后，证据选择、假设排名和预测未来应系统性改变；证据不足时，它应追问或拒绝过度判断。</div>`}
];
let current=0,mode='paper',wheelLock=false;
const deck=document.querySelector('#deck'),progress=document.querySelector('#progress'),counter=document.querySelector('#counter');
slides.forEach((s,i)=>{const el=document.createElement('section');el.className='slide';el.innerHTML=`<div class="slide-inner"><div class="kicker">${s.k}</div><h1 class="title">${s.t}</h1>${s.html}</div>`;deck.append(el);const b=document.createElement('button');b.title=s.t;b.onclick=()=>go(i);progress.append(b)});
const slideEls=[...document.querySelectorAll('.slide')],dots=[...progress.children];
function go(n){current=Math.max(0,Math.min(slides.length-1,n));slideEls.forEach((x,i)=>x.classList.toggle('active',i===current));dots.forEach((x,i)=>x.classList.toggle('active',i===current));counter.textContent=`${String(current+1).padStart(2,'0')} / ${slides.length}`;renderEvidence()}
function step(d){go(current+d)}
function renderEvidence(){const e=evidence[current];document.querySelector('#evidenceContent').innerHTML=`<div class="source-meta">${e.page}</div><span class="tag ${e.type.includes('论文')&&!e.type.includes('我们')?'paper':''}">${e.type}</span><h3>Original</h3>${e.quotes.map(q=>`<div class="original">“${q}”</div>`).join('')}<h3>What this means · 中文解读</h3><p class="meaning">${e.meaning}</p>`}
function drawer(open){document.querySelector('#evidenceDrawer').classList.toggle('open',open);document.querySelector('#evidenceDrawer').setAttribute('aria-hidden',!open);document.querySelector('#scrim').classList.toggle('open',open)}
function overview(open){document.querySelector('#overview').classList.toggle('open',open);document.querySelector('#overview').setAttribute('aria-hidden',!open)}
document.querySelector('#evidenceBtn').onclick=()=>drawer(true);document.querySelector('#closeDrawer').onclick=()=>drawer(false);document.querySelector('#scrim').onclick=()=>drawer(false);document.querySelector('#menuBtn').onclick=()=>overview(true);document.querySelector('#closeOverview').onclick=()=>overview(false);
document.querySelector('#overviewGrid').innerHTML=slides.map((s,i)=>`<button class="thumb" data-i="${i}"><b>${String(i+1).padStart(2,'0')}</b><span>${s.t}</span></button>`).join('');document.querySelector('#overviewGrid').onclick=e=>{const b=e.target.closest('.thumb');if(b){go(+b.dataset.i);overview(false)}};
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;document.body.dataset.mode=mode;document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('active',x===b))});document.querySelector('#fullscreenBtn').onclick=()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen();
addEventListener('keydown',e=>{if(e.key==='Escape'){drawer(false);overview(false);return}if(['ArrowRight','ArrowDown',' '].includes(e.key)){e.preventDefault();step(1)}if(['ArrowLeft','ArrowUp'].includes(e.key)){e.preventDefault();step(-1)}if(e.key.toLowerCase()==='o')overview(true);if(e.key.toLowerCase()==='f')document.querySelector('#fullscreenBtn').click()});addEventListener('wheel',e=>{if(wheelLock||document.querySelector('.drawer.open,.overview.open'))return;wheelLock=true;step(e.deltaY>0?1:-1);setTimeout(()=>wheelLock=false,650)},{passive:true});let sx=0;addEventListener('touchstart',e=>sx=e.touches[0].clientX,{passive:true});addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-sx;if(Math.abs(dx)>50)step(dx<0?1:-1)},{passive:true});document.body.dataset.mode=mode;go(0);
